// Function to identify sentiment type from text (based on Alpha Vantage labels or AI recommendation)
function getSentimentType(text) {
  if (!text) return 'neutral';

  const lowerText = text.toLowerCase();

  // Primary checks for overall categories
  if (lowerText.includes('very bearish') || lowerText.includes('somewhat-bearish') || lowerText.includes('bearish') || lowerText.includes('negative') || lowerText.includes('sell')) {
    return 'negative';
  }

  if (lowerText.includes('very bullish') || lowerText.includes('somewhat-bullish') || lowerText.includes('bullish') || lowerText.includes('positive') || lowerText.includes('buy')) {
    return 'positive';
  }

  // Default to neutral for "neutral" or "hold"
  return 'neutral';
}

// Function to check if a specific text belongs to a sentiment - used for bug fixing
function debugSentiment(text) {
  console.log(`Sentiment check: "${text}" => ${getSentimentType(text)}`);
}

// New function to remove undefined articles from HTML
function removeUndefinedArticles(html) {
  // Find all article blocks
  const articleBlocksRegex = /<tr>\s*<td style="padding-bottom: 16px;">\s*<table[^>]*>[\s\S]*?<\/table>\s*<\/td>\s*<\/tr>/g;
  const articleBlocks = Array.from(html.matchAll(articleBlocksRegex));

  // No articles found
  if (!articleBlocks || articleBlocks.length === 0) {
    console.log("No article blocks found");
    return html;
  }

  // Function to check if an article is fully undefined
  function isFullyUndefinedArticle(articleHtml) {
    // An article is considered fully undefined if:
    // 1. It has href="undefined"
    // 2. It has link text that is "undefined"
    // 3. It has "undefined | undefined" (source and date)
    return articleHtml.includes('href="undefined"') &&
           articleHtml.includes('>undefined</a>') &&
           articleHtml.includes('undefined | undefined');
  }

  // Identify blocks to remove
  const blocksToRemove = [];
  for (const match of articleBlocks) {
    const block = match[0];
    if (isFullyUndefinedArticle(block)) {
      console.log("Found undefined article, will remove");
      blocksToRemove.push(match);
    } else {
      console.log("Found valid article, keeping it");
    }
  }

  // If no blocks to remove, return original HTML
  if (blocksToRemove.length === 0) {
    console.log("No undefined articles found to remove");
    return html;
  }

  console.log(`Found ${blocksToRemove.length} undefined articles to remove`);

  // Create a new string by removing the matches from end to start (to avoid index shifting)
  let cleanedHtml = html;
  for (let i = blocksToRemove.length - 1; i >= 0; i--) {
    const match = blocksToRemove[i];
    cleanedHtml = cleanedHtml.slice(0, match.index) + cleanedHtml.slice(match.index + match[0].length);
  }

  return cleanedHtml;
}

// Get the HTML from the specified parameter
const html = $input.first().json.html;
let updatedHtml = html;

// Debug checks - check several keywords that might appear
// These are for testing the `getSentimentType` function during development.
// They can be removed in a production environment.
debugSentiment("Bullish");
debugSentiment("Bearish");
debugSentiment("Neutral");
debugSentiment("Very Bullish");
debugSentiment("Very Bearish");
debugSentiment("Somewhat-Bullish");
debugSentiment("Somewhat-Bearish");
debugSentiment("Buy");
debugSentiment("Sell");
debugSentiment("Hold");


// 1. Update colors in the recommendation title
const titleMatch = html.match(/<h2 style="[^"]*color: #[a-f0-9]+;[^"]*">([^<]+)<\/h2>/i);
if (titleMatch) {
  const titleText = titleMatch[1].trim();
  const titleSentiment = getSentimentType(titleText);

  // Update title color
  updatedHtml = updatedHtml.replace(
    /(<h2 style="[^"]*color: )#[a-f0-9]+(;[^"]*">)/i,
    `$1${colors[titleSentiment].main}$2`
  );

  // Update side bar color
  updatedHtml = updatedHtml.replace(
    /(<div style="position: absolute; right: 0; top: 0; bottom: 0; width: 6px; background-color: )#[a-f0-9]+(;"><\/div>)/i,
    `$1${colors[titleSentiment].main}$2`
  );

  // Update gradient color
  updatedHtml = updatedHtml.replace(
    /(<div style="position: absolute; right: 0; top: 0; width: 100%; height: 100%; background: linear-gradient\(90deg, )rgba\([^)]+\)( 0%, )rgba\([^)]+\)( 50%\);"><\/div>)/i,
    `$1${colors[titleSentiment].gradient}$2${colors[titleSentiment].gradient.replace('0.07', '0')}$3`
  );

  // Update icon background color
  updatedHtml = updatedHtml.replace(
    /(<div style="display: inline-block; width: 40px; height: 40px; border-radius: 50%; margin-bottom: 10px; background-color: )rgba\([^)]+\)(; text-align: center;">)/i,
    `$1${colors[titleSentiment].background}$2`
  );
}

// 2. Update overall sentiment color
const sentimentMatch = updatedHtml.match(/<span style="[^"]*font-weight: 600; color: #[a-f0-9]+;[^"]*">([^<]+)<\/span>/i);
if (sentimentMatch) {
  const sentimentText = sentimentMatch[1].trim();
  const sentimentType = getSentimentType(sentimentText);

  updatedHtml = updatedHtml.replace(
    /(<span style="[^"]*font-weight: 600; color: )#[a-f0-9]+(;[^"]*">)/i,
    `$1${colors[sentimentType].main}$2`
  );
}

// 3. Update article colors
const articleBlocks = updatedHtml.match(/<tr>\s*<td style="padding-bottom: 16px;">\s*<table[^>]*>[\s\S]*?<\/table>\s*<\/td>\s*<\/tr>/g);
if (articleBlocks) {
  for (const block of articleBlocks) {
    // Check if this is a fully undefined article before skipping
    const isUndefined = block.includes('href="undefined"') &&
                        block.includes('>undefined</a>') &&
                        block.includes('undefined | undefined');

    // Skip if this is a completely undefined article
    if (isUndefined) {
      console.log("Skipping color update for undefined article");
      continue;
    }

    // Find sentiment within the block
    const articleSentimentMatch = block.match(/<div style="[^"]*padding: 3px 10px;[^"]*">([^<]+)<\/div>/i);
    if (articleSentimentMatch) {
      const articleSentimentText = articleSentimentMatch[1].trim();
      const articleSentimentType = getSentimentType(articleSentimentText);

      // Debug check - log the identified sentiment
      debugSentiment(articleSentimentText);

      // Create updated block
      let updatedBlock = block;

      // Update side line color
      updatedBlock = updatedBlock.replace(
        /(<td width="4" style="background-color: )#[a-f0-9]+(;"><\/td>)/i,
        `$1${colors[articleSentimentType].main}$2`
      );

      // Update sentiment tag colors (background and text color)
      updatedBlock = updatedBlock.replace(
        /(<div style="[^"]*background-color: )rgba\([^)]+\)(; color: )#[a-f0-9]+(;[^"]*">)/i,
        `$1${colors[articleSentimentType].accent}$2${colors[articleSentimentType].main}$3`
      );

      // Replace the block with its updated version
      updatedHtml = updatedHtml.replace(block, updatedBlock);
    }
  }
}

// 4. Update recommendation button color
const buttonMatch = updatedHtml.match(/<a style="[^"]*background-color: #[a-f0-9]+;[^"]*">([^<]+)<\/a>/i);
if (buttonMatch) {
  const buttonText = buttonMatch[1].trim();
  let buttonSentiment = 'neutral'; // Default

  // Determine sentiment based on button text (from AI's "Recommendation" field)
  if (buttonText.includes("Buy")) {
    buttonSentiment = 'positive';
  } else if (buttonText.includes("Sell")) {
    buttonSentiment = 'negative';
  } else if (buttonText.includes("Hold")) {
    buttonSentiment = 'neutral';
  }

  // Update button background color
  updatedHtml = updatedHtml.replace(
    /(<a style="[^"]*background-color: )#[a-f0-9]+(;[^"]*">)/i,
    `$1${colors[buttonSentiment].main}$2`
  );

  // Update box-shadow color
  const boxShadowRgba = `rgba(${parseInt(colors[buttonSentiment].main.substring(1, 3), 16)}, ${parseInt(colors[buttonSentiment].main.substring(3, 5), 16)}, ${parseInt(colors[buttonSentiment].main.substring(5, 7), 16)}, 0.25)`;
  updatedHtml = updatedHtml.replace(
    /(box-shadow: 0 4px 6px )rgba\([^)]+\)(;[^"]*">)/i,
    `$1${boxShadowRgba}$2`
  );
}

// 5. Remove undefined articles
updatedHtml = removeUndefinedArticles(updatedHtml);

// 6. Remove topics with only one article
updatedHtml = removeSingleArticleTopics(updatedHtml);

// Return updated HTML
return { html: updatedHtml };
